-- Phase 2: completes admission-discharge-transfer, bed management, and inpatient
-- billing against Patient_admission.docx:
--   * bed placement matches clinical needs (telemetry, intensive care, isolation)
--   * direct admissions and regional transfers without a completed triage
--   * in-hospital bed transfers
--   * bed status follows the patient; cleaning turnaround is recorded
--   * daily room charges from the facility chargemaster (no invented prices)
--   * atomic claim preparation and payer adjudication (CARC/RARC)
--   * role-scoped access and locked charges once an account is claimed

-- 1. New columns ------------------------------------------------------------------
alter table public.inpatient_admissions
 add column if not exists placement_override_reason text,
 add column if not exists admitted_without_triage_reason text;
alter table public.inpatient_beds add column if not exists accommodation_charge_item_id uuid references public.facility_chargemaster_items(id);
alter table public.inpatient_charge_items
 add column if not exists chargemaster_item_id uuid references public.facility_chargemaster_items(id),
 add column if not exists bed_assignment_id uuid references public.inpatient_bed_assignments(id),
 add column if not exists correction_reason text;
create unique index if not exists inpatient_room_charge_once_per_day on public.inpatient_charge_items(account_id,bed_assignment_id,((occurred_at at time zone 'UTC')::date))
 where bed_assignment_id is not null and status<>'entered_in_error';

create table if not exists public.inpatient_bed_status_events(
 id bigint generated by default as identity primary key,
 facility_id uuid not null references public.facilities(id) on delete cascade,
 bed_id uuid not null references public.inpatient_beds(id) on delete cascade,
 from_status text, to_status text not null, changed_at timestamptz not null default now(), changed_by uuid
);
create index if not exists inpatient_bed_status_events_bed_idx on public.inpatient_bed_status_events(bed_id,changed_at);

-- 2. Role helpers ---------------------------------------------------------------------
create or replace function private.can_manage_inpatient(fid uuid) returns boolean language sql stable security invoker set search_path='' as $$
 select private.is_platform_root() or private.has_facility_role(fid,array['physician','resident','advanced_practice','nurse','registration','case_manager','sysadmin'])
$$;
create or replace function private.can_bill_inpatient(fid uuid) returns boolean language sql stable security invoker set search_path='' as $$
 select private.is_platform_root() or private.has_facility_role(fid,array['billing','case_manager','him','sysadmin'])
$$;
revoke all on function private.can_manage_inpatient(uuid),private.can_bill_inpatient(uuid) from public,anon;
grant execute on function private.can_manage_inpatient(uuid),private.can_bill_inpatient(uuid) to authenticated;

-- Explains why a bed does not meet the admission's clinical needs, or returns null.
create or replace function private.bed_placement_problem(target_bed uuid,acuity text,isolation text) returns text language sql stable security definer set search_path='' as $$
 select case
  when acuity='telemetry' and not b.telemetry then 'Telemetry level of care needs a bed with telemetry monitoring'
  when acuity='intensive_care' and lower(b.bed_type) not in ('intensive care','intensive_care') then 'Intensive care needs an intensive-care bed'
  when nullif(lower(btrim(coalesce(isolation,''))),'') is not null and lower(btrim(isolation)) not in ('none','no') and lower(isolation) like '%airborne%' and not b.negative_pressure then 'Airborne isolation needs a negative-pressure bed'
  when nullif(lower(btrim(coalesce(isolation,''))),'') is not null and lower(btrim(isolation)) not in ('none','no') and not (b.isolation_capable or b.negative_pressure) then 'Isolation needs an isolation-capable bed'
  else null end
 from public.inpatient_beds b where b.id=target_bed
$$;
revoke all on function private.bed_placement_problem(uuid,text,text) from public,anon;
grant execute on function private.bed_placement_problem(uuid,text,text) to authenticated;

-- 3. Admission ---------------------------------------------------------------------------
drop function if exists public.admit_inpatient(uuid,bigint,bigint,bigint,uuid,text,text,text,text,text,timestamptz,uuid);
create or replace function public.admit_inpatient(
 target_facility uuid, target_patient bigint, target_service bigint, target_provider bigint,
 target_bed uuid, source_text text, acuity_text text, isolation_text text,
 diagnosis_code_text text, diagnosis_display_text text, admission_time timestamptz,
 coverage_id uuid default null, triage_bypass_reason text default null, placement_override_reason text default null
) returns uuid language plpgsql security invoker set search_path='' as $$
declare new_encounter bigint; new_admission uuid; new_account text; problem text; bypass text:=nullif(btrim(coalesce(triage_bypass_reason,'')),''); override text:=nullif(btrim(coalesce(placement_override_reason,'')),'');
begin
 if not private.can_manage_inpatient(target_facility) then raise exception 'Only clinical, registration, or case-management staff of this facility can admit patients'; end if;
 if not exists(select 1 from public.patients p where p.id=target_patient and p.facility_id=target_facility) then raise exception 'Patient is not registered at the selected facility'; end if;
 if exists(select 1 from public.inpatient_admissions a where a.patient_id=target_patient and a.admission_status in ('pending','admitted')) then raise exception 'This patient already has an active admission'; end if;
 if not exists(select 1 from public.inpatient_beds b where b.id=target_bed and b.facility_id=target_facility and b.active and b.operational_status='available') then raise exception 'Selected bed is not available'; end if;
 problem:=private.bed_placement_problem(target_bed,acuity_text,isolation_text);
 if problem is not null and override is null then raise exception '%. Choose a matching bed or record a placement override reason.',problem; end if;
 insert into public.encounters(patient_id,encounter_type,service_id,start_at,attending_provider_id,status,triage_skipped,triage_skip_reason,triage_skipped_by)
 values(target_patient,'Inpatient',target_service,admission_time,target_provider,'open',bypass is not null,bypass,case when bypass is not null then (select auth.uid()) end) returning id into new_encounter;
 insert into public.inpatient_admissions(facility_id,patient_id,encounter_id,admission_status,admission_source,acuity_level,isolation_requirement,diagnosis_code,diagnosis_display,admitting_provider_id,admitted_at,created_by,placement_override_reason,admitted_without_triage_reason)
 values(target_facility,target_patient,new_encounter,'admitted',source_text,acuity_text,nullif(isolation_text,''),nullif(diagnosis_code_text,''),nullif(diagnosis_display_text,''),target_provider,admission_time,(select auth.uid()),case when problem is not null then override end,bypass) returning id into new_admission;
 insert into public.inpatient_bed_assignments(facility_id,admission_id,bed_id,assignment_status,assigned_at,occupied_at,assigned_by)
 values(target_facility,new_admission,target_bed,'active',admission_time,admission_time,(select auth.uid()));
 update public.inpatient_beds set operational_status='occupied',updated_at=now() where id=target_bed;
 new_account:='IP-'||to_char(admission_time,'YYYYMMDD')||'-'||upper(substr(replace(new_admission::text,'-',''),1,8));
 insert into public.inpatient_accounts(facility_id,patient_id,admission_id,account_number,insurance_enrollment_id,service_period_start)
 values(target_facility,target_patient,new_admission,new_account,coverage_id,admission_time::date);
 return new_admission;
end $$;
revoke all on function public.admit_inpatient(uuid,bigint,bigint,bigint,uuid,text,text,text,text,text,timestamptz,uuid,text,text) from public,anon;
grant execute on function public.admit_inpatient(uuid,bigint,bigint,bigint,uuid,text,text,text,text,text,timestamptz,uuid,text,text) to authenticated;

-- 4. Transfer between beds ---------------------------------------------------------------
create or replace function public.transfer_inpatient_bed(target_admission uuid,target_bed uuid,transfer_reason text,placement_override_reason text default null,transfer_time timestamptz default now())
returns void language plpgsql security invoker set search_path='' as $$
declare adm public.inpatient_admissions%rowtype; old_bed uuid; problem text; override text:=nullif(btrim(coalesce(placement_override_reason,'')),'');
begin
 select * into adm from public.inpatient_admissions where id=target_admission;
 if adm.id is null or not private.can_manage_inpatient(adm.facility_id) then raise exception 'Admission not found or not authorized'; end if;
 if adm.admission_status<>'admitted' then raise exception 'Only admitted patients can be transferred'; end if;
 if nullif(btrim(coalesce(transfer_reason,'')),'') is null then raise exception 'A transfer reason is required'; end if;
 if not exists(select 1 from public.inpatient_beds b where b.id=target_bed and b.facility_id=adm.facility_id and b.active and b.operational_status='available') then raise exception 'Selected bed is not available'; end if;
 problem:=private.bed_placement_problem(target_bed,adm.acuity_level,adm.isolation_requirement);
 if problem is not null and override is null then raise exception '%. Choose a matching bed or record a placement override reason.',problem; end if;
 select bed_id into old_bed from public.inpatient_bed_assignments where admission_id=target_admission and released_at is null and assignment_status in ('reserved','active');
 update public.inpatient_bed_assignments set assignment_status='released',released_at=transfer_time,release_reason='transfer: '||btrim(transfer_reason)||coalesce(' (placement override: '||case when problem is not null then override end||')','')
  where admission_id=target_admission and released_at is null;
 if old_bed is not null then update public.inpatient_beds set operational_status='needs_cleaning',updated_at=now() where id=old_bed; end if;
 insert into public.inpatient_bed_assignments(facility_id,admission_id,bed_id,assignment_status,assigned_at,occupied_at,assigned_by)
 values(adm.facility_id,target_admission,target_bed,'active',transfer_time,transfer_time,(select auth.uid()));
 update public.inpatient_beds set operational_status='occupied',updated_at=now() where id=target_bed;
end $$;
revoke all on function public.transfer_inpatient_bed(uuid,uuid,text,text,timestamptz) from public,anon;
grant execute on function public.transfer_inpatient_bed(uuid,uuid,text,text,timestamptz) to authenticated;

-- 5. Bed status follows the patient; every change is recorded for turnaround metrics.
create or replace function private.guard_bed_status() returns trigger language plpgsql security definer set search_path='' as $$
declare assigned boolean;
begin
 if tg_op='UPDATE' and new.operational_status is not distinct from old.operational_status then return new; end if;
 if tg_op='UPDATE' then
  assigned:=exists(select 1 from public.inpatient_bed_assignments a where a.bed_id=new.id and a.released_at is null and a.assignment_status in ('reserved','active'));
  if assigned and new.operational_status<>'occupied' then raise exception 'This bed has a patient assigned; discharge or transfer the patient first'; end if;
  if not assigned and new.operational_status='occupied' then raise exception 'A bed becomes occupied only through an admission or transfer'; end if;
  if (select auth.uid()) is not null and (new.operational_status in ('blocked','out_of_service') or old.operational_status in ('blocked','out_of_service'))
     and not private.can_manage_inpatient(new.facility_id) then
   raise exception 'Only clinical or administrative staff can block or release a bed';
  end if;
 end if;
 return new;
end $$;
-- Recorded after the row exists, so a new bed's first status is logged too.
create or replace function private.record_bed_status() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and new.operational_status is not distinct from old.operational_status then return null; end if;
 insert into public.inpatient_bed_status_events(facility_id,bed_id,from_status,to_status,changed_by)
 values(new.facility_id,new.id,case when tg_op='UPDATE' then old.operational_status end,new.operational_status,(select auth.uid()));
 return null;
end $$;
revoke all on function private.guard_bed_status(),private.record_bed_status() from public,anon,authenticated;
drop trigger if exists guard_bed_status on public.inpatient_beds;
create trigger guard_bed_status before update of operational_status on public.inpatient_beds for each row execute function private.guard_bed_status();
drop trigger if exists record_bed_status on public.inpatient_beds;
create trigger record_bed_status after insert or update of operational_status on public.inpatient_beds for each row execute function private.record_bed_status();

-- Minutes from "needs cleaning" to "available" for each cleaning cycle.
create or replace view public.inpatient_bed_turnaround with (security_invoker=true) as
select e.facility_id,e.bed_id,e.changed_at as needs_cleaning_at,
 (select min(x.changed_at) from public.inpatient_bed_status_events x where x.bed_id=e.bed_id and x.to_status='cleaning' and x.changed_at>=e.changed_at) as cleaning_started_at,
 (select min(x.changed_at) from public.inpatient_bed_status_events x where x.bed_id=e.bed_id and x.to_status='available' and x.changed_at>=e.changed_at) as available_at,
 round(extract(epoch from ((select min(x.changed_at) from public.inpatient_bed_status_events x where x.bed_id=e.bed_id and x.to_status='available' and x.changed_at>=e.changed_at)-e.changed_at))/60) as turnaround_minutes
from public.inpatient_bed_status_events e where e.to_status='needs_cleaning';
grant select on public.inpatient_bed_turnaround to authenticated;

-- 6. Access: billing staff read clinical placement but cannot change it; clinical staff
-- cannot touch claims. Roles are checked at the admission's facility, not globally.
alter table public.inpatient_bed_status_events enable row level security;
create policy bed_status_events_read on public.inpatient_bed_status_events for select to authenticated using(private.is_aal2() and (private.is_platform_root() or private.is_facility_member(facility_id)));
revoke insert,update,delete on public.inpatient_bed_status_events from anon,authenticated;
grant select on public.inpatient_bed_status_events to authenticated;

drop policy if exists inpatient_admissions_access on public.inpatient_admissions;
create policy inpatient_admissions_read on public.inpatient_admissions for select to authenticated using(private.is_aal2() and (private.is_platform_root() or private.is_facility_member(facility_id)));
create policy inpatient_admissions_write on public.inpatient_admissions for insert to authenticated with check(private.is_aal2() and private.can_manage_inpatient(facility_id));
create policy inpatient_admissions_update on public.inpatient_admissions for update to authenticated using(private.is_aal2() and private.can_manage_inpatient(facility_id)) with check(private.is_aal2() and private.can_manage_inpatient(facility_id));

drop policy if exists inpatient_beds_access on public.inpatient_beds;
create policy inpatient_beds_read on public.inpatient_beds for select to authenticated using(private.is_aal2() and (private.is_platform_root() or private.is_facility_member(facility_id)));
create policy inpatient_beds_insert on public.inpatient_beds for insert to authenticated with check(private.is_aal2() and private.can_manage_inpatient(facility_id));
-- Any facility member (including environmental services) may progress cleaning; the trigger guards the rest.
create policy inpatient_beds_update on public.inpatient_beds for update to authenticated using(private.is_aal2() and (private.is_platform_root() or private.is_facility_member(facility_id))) with check(private.is_aal2() and (private.is_platform_root() or private.is_facility_member(facility_id)));

drop policy if exists inpatient_bed_assignments_access on public.inpatient_bed_assignments;
create policy inpatient_bed_assignments_read on public.inpatient_bed_assignments for select to authenticated using(private.is_aal2() and (private.is_platform_root() or private.is_facility_member(facility_id)));
create policy inpatient_bed_assignments_write on public.inpatient_bed_assignments for insert to authenticated with check(private.is_aal2() and private.can_manage_inpatient(facility_id));
create policy inpatient_bed_assignments_update on public.inpatient_bed_assignments for update to authenticated using(private.is_aal2() and private.can_manage_inpatient(facility_id)) with check(private.is_aal2() and private.can_manage_inpatient(facility_id));
revoke delete on public.inpatient_admissions,public.inpatient_bed_assignments,public.inpatient_accounts,public.inpatient_charge_items,public.inpatient_claims,public.inpatient_claim_adjudications from anon,authenticated;

drop policy if exists inpatient_accounts_access on public.inpatient_accounts;
create policy inpatient_accounts_read on public.inpatient_accounts for select to authenticated using(private.is_aal2() and (private.can_manage_inpatient(facility_id) or private.can_bill_inpatient(facility_id)));
create policy inpatient_accounts_insert on public.inpatient_accounts for insert to authenticated with check(private.is_aal2() and (private.can_manage_inpatient(facility_id) or private.can_bill_inpatient(facility_id)));
create policy inpatient_accounts_update on public.inpatient_accounts for update to authenticated using(private.is_aal2() and (private.can_manage_inpatient(facility_id) or private.can_bill_inpatient(facility_id))) with check(private.is_aal2() and (private.can_manage_inpatient(facility_id) or private.can_bill_inpatient(facility_id)));

drop policy if exists inpatient_charge_items_access on public.inpatient_charge_items;
create policy inpatient_charge_items_read on public.inpatient_charge_items for select to authenticated using(private.is_aal2() and (private.can_manage_inpatient(facility_id) or private.can_bill_inpatient(facility_id)));
create policy inpatient_charge_items_insert on public.inpatient_charge_items for insert to authenticated with check(private.is_aal2() and created_by=(select auth.uid()) and (private.can_manage_inpatient(facility_id) or private.can_bill_inpatient(facility_id)));
create policy inpatient_charge_items_update on public.inpatient_charge_items for update to authenticated using(private.is_aal2() and private.can_bill_inpatient(facility_id)) with check(private.is_aal2() and private.can_bill_inpatient(facility_id));

drop policy if exists inpatient_claims_access on public.inpatient_claims;
create policy inpatient_claims_read on public.inpatient_claims for select to authenticated using(private.is_aal2() and private.can_bill_inpatient(facility_id));
create policy inpatient_claims_write on public.inpatient_claims for insert to authenticated with check(private.is_aal2() and private.can_bill_inpatient(facility_id));
create policy inpatient_claims_update on public.inpatient_claims for update to authenticated using(private.is_aal2() and private.can_bill_inpatient(facility_id)) with check(private.is_aal2() and private.can_bill_inpatient(facility_id));

drop policy if exists inpatient_claim_adjudications_access on public.inpatient_claim_adjudications;
create policy inpatient_claim_adjudications_read on public.inpatient_claim_adjudications for select to authenticated using(private.is_aal2() and exists(select 1 from public.inpatient_claims c where c.id=claim_id and private.can_bill_inpatient(c.facility_id)));
create policy inpatient_claim_adjudications_write on public.inpatient_claim_adjudications for insert to authenticated with check(private.is_aal2() and exists(select 1 from public.inpatient_claims c where c.id=claim_id and private.can_bill_inpatient(c.facility_id)));
revoke update on public.inpatient_claim_adjudications from anon,authenticated;

-- Charge lines on the Billing Department screen name patients: staff need MFA.
drop policy if exists mfa_required on public.facility_charge_lines;
create policy mfa_required on public.facility_charge_lines as restrictive for all to authenticated using(private.is_aal2()) with check(private.is_aal2());

-- 7. Charges: chargemaster prices, and no silent edits ------------------------------------
create or replace function private.guard_inpatient_charge() returns trigger language plpgsql security definer set search_path='' as $$
declare acct public.inpatient_accounts%rowtype; item public.facility_chargemaster_items%rowtype;
begin
 select * into acct from public.inpatient_accounts where id=new.account_id;
 if acct.id is null or acct.facility_id<>new.facility_id then raise exception 'Charge must belong to an inpatient account of the same facility'; end if;
 if tg_op='INSERT' then
  if acct.status not in ('active','ready_to_claim') then raise exception 'This account has already been claimed; its charges are locked'; end if;
  if new.chargemaster_item_id is not null then
   select * into item from public.facility_chargemaster_items where id=new.chargemaster_item_id and facility_id=new.facility_id and active;
   if item.id is null then raise exception 'An active chargemaster item from this facility is required'; end if;
   new.code_system:='NUBC Revenue Code'; new.code:=item.revenue_code; new.description:=item.charge_description; new.unit:=item.unit_of_service; new.unit_price:=item.unit_price;
  end if;
  new.status:=case when new.status='planned' then 'planned' else 'billable' end;
  return new;
 end if;
 -- Updates: only status moves are allowed, and every other field is fixed.
 if (to_jsonb(new)-'status'-'correction_reason'-'total_amount')<>(to_jsonb(old)-'status'-'correction_reason'-'total_amount') then raise exception 'Charge details cannot be edited; mark the charge entered in error and post a corrected one'; end if;
 if new.status='entered_in_error' then
  if old.status='billed' then raise exception 'A billed charge cannot be removed; adjust it through the claim'; end if;
  if nullif(btrim(coalesce(new.correction_reason,'')),'') is null then raise exception 'A reason is required to mark a charge entered in error'; end if;
 elsif not (old.status in ('planned','billable') and new.status in ('billable','billed')) then
  raise exception 'Charge status cannot move from % to %',old.status,new.status;
 end if;
 return new;
end $$;
revoke all on function private.guard_inpatient_charge() from public,anon,authenticated;
drop trigger if exists guard_inpatient_charge on public.inpatient_charge_items;
create trigger guard_inpatient_charge before insert or update on public.inpatient_charge_items for each row execute function private.guard_inpatient_charge();

-- Posts one accommodation charge per calendar day in each bed, priced from the bed's
-- chargemaster item. Days already charged are skipped. Beds without a configured
-- room charge are skipped and reported.
create or replace function public.post_inpatient_room_charges(target_account uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
declare acct public.inpatient_accounts%rowtype; a record; d date; last_day date; posted integer:=0; unpriced integer:=0; encounter bigint;
begin
 select * into acct from public.inpatient_accounts where id=target_account;
 if acct.id is null or not (private.can_manage_inpatient(acct.facility_id) or private.can_bill_inpatient(acct.facility_id)) then raise exception 'Account not found or not authorized'; end if;
 if acct.status not in ('active','ready_to_claim') then raise exception 'This account has already been claimed; its charges are locked'; end if;
 select encounter_id into encounter from public.inpatient_admissions where id=acct.admission_id;
 for a in select ba.id,ba.occupied_at,ba.released_at,b.accommodation_charge_item_id from public.inpatient_bed_assignments ba join public.inpatient_beds b on b.id=ba.bed_id
          where ba.admission_id=acct.admission_id and ba.occupied_at is not null and ba.assignment_status in ('active','released') order by ba.occupied_at loop
  if a.accommodation_charge_item_id is null then unpriced:=unpriced+1; continue; end if;
  -- Midnight census: the day a patient leaves a bed is not charged, except a same-day stay counts once.
  last_day:=case when a.released_at is null then current_date-1 else (a.released_at at time zone 'UTC')::date-1 end;
  if a.released_at is not null and last_day<(a.occupied_at at time zone 'UTC')::date then last_day:=(a.occupied_at at time zone 'UTC')::date; end if;
  d:=(a.occupied_at at time zone 'UTC')::date;
  while d<=last_day loop
   if not exists(select 1 from public.inpatient_charge_items c where c.account_id=acct.id and c.bed_assignment_id=a.id and (c.occurred_at at time zone 'UTC')::date=d and c.status<>'entered_in_error') then
    insert into public.inpatient_charge_items(facility_id,account_id,encounter_id,code_system,code,description,occurred_at,quantity,unit,unit_price,created_by,chargemaster_item_id,bed_assignment_id)
    values(acct.facility_id,acct.id,encounter,'NUBC Revenue Code','0000','Room charge',(d::timestamp at time zone 'UTC')+interval '12 hours',1,'day',0,(select auth.uid()),a.accommodation_charge_item_id,a.id);
    posted:=posted+1;
   end if;
   d:=d+1;
  end loop;
 end loop;
 return jsonb_build_object('posted',posted,'beds_without_room_charge',unpriced);
end $$;
revoke all on function public.post_inpatient_room_charges(uuid) from public,anon;
grant execute on function public.post_inpatient_room_charges(uuid) to authenticated;

-- 8. Discharge: only once, posts room charges, then readies the account --------------------
create or replace function public.discharge_inpatient(target_admission uuid, discharge_time timestamptz default now()) returns void language plpgsql security invoker set search_path='' as $$
declare adm public.inpatient_admissions%rowtype; target_bed uuid; acct uuid;
begin
 select * into adm from public.inpatient_admissions where id=target_admission;
 if adm.id is null or not private.can_manage_inpatient(adm.facility_id) then raise exception 'Admission not found or not authorized'; end if;
 if adm.admission_status<>'admitted' then raise exception 'This admission is already %',adm.admission_status; end if;
 select bed_id into target_bed from public.inpatient_bed_assignments where admission_id=target_admission and released_at is null and assignment_status in ('reserved','active') limit 1;
 update public.inpatient_admissions set admission_status='discharged',discharge_ordered_at=coalesce(discharge_ordered_at,discharge_time),discharged_at=discharge_time,updated_at=now() where id=target_admission;
 update public.encounters set status='closed',end_at=discharge_time where id=adm.encounter_id;
 update public.inpatient_bed_assignments set assignment_status='released',released_at=discharge_time,release_reason='discharge' where admission_id=target_admission and released_at is null;
 if target_bed is not null then update public.inpatient_beds set operational_status='needs_cleaning',updated_at=now() where id=target_bed; end if;
 select id into acct from public.inpatient_accounts where admission_id=target_admission and status='active';
 if acct is not null then perform public.post_inpatient_room_charges(acct); end if;
 update public.inpatient_accounts set status='ready_to_claim',service_period_end=discharge_time::date where admission_id=target_admission and status='active';
end $$;

-- 9. Claims ---------------------------------------------------------------------------------
create or replace function public.create_inpatient_claim(target_account uuid) returns uuid language plpgsql security invoker set search_path='' as $$
declare acct public.inpatient_accounts%rowtype; total numeric(12,2); new_claim uuid;
begin
 select * into acct from public.inpatient_accounts where id=target_account for update;
 if acct.id is null or not private.can_bill_inpatient(acct.facility_id) then raise exception 'Account not found or not authorized'; end if;
 if acct.status<>'ready_to_claim' then raise exception 'Only discharged accounts that are ready to claim can be claimed'; end if;
 if exists(select 1 from public.inpatient_claims c where c.account_id=acct.id and c.status<>'void') then raise exception 'This account already has a claim'; end if;
 select coalesce(sum(total_amount),0) into total from public.inpatient_charge_items where account_id=acct.id and status='billable';
 if total<=0 then raise exception 'There are no billable charges on this account'; end if;
 insert into public.inpatient_claims(facility_id,account_id,claim_number,status,submitted_amount,submitted_at)
 values(acct.facility_id,acct.id,'CLM-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(acct.id::text,'-',''),1,8)),'submitted',total,now()) returning id into new_claim;
 update public.inpatient_charge_items set status='billed' where account_id=acct.id and status='billable';
 update public.inpatient_accounts set status='submitted' where id=acct.id;
 return new_claim;
end $$;
revoke all on function public.create_inpatient_claim(uuid) from public,anon;
grant execute on function public.create_inpatient_claim(uuid) to authenticated;

create or replace function public.record_inpatient_claim_adjudication(target_claim uuid,claim_outcome text,benefit numeric,patient_share numeric,payer_ref text default null,carc text default null,rarc text default null,note text default null)
returns void language plpgsql security invoker set search_path='' as $$
declare c public.inpatient_claims%rowtype;
begin
 select * into c from public.inpatient_claims where id=target_claim for update;
 if c.id is null or not private.can_bill_inpatient(c.facility_id) then raise exception 'Claim not found or not authorized'; end if;
 if c.status not in ('submitted','accepted') then raise exception 'Only submitted claims can be adjudicated'; end if;
 if claim_outcome not in ('paid','partially_paid','denied') then raise exception 'Outcome must be paid, partially_paid, or denied'; end if;
 if benefit<0 or patient_share<0 or benefit+patient_share>c.submitted_amount then raise exception 'Paid and patient amounts must be zero or more and cannot exceed the submitted amount'; end if;
 if claim_outcome='denied' and nullif(btrim(coalesce(carc,'')),'') is null then raise exception 'A denial needs a Claim Adjustment Reason Code (CARC)'; end if;
 insert into public.inpatient_claim_adjudications(claim_id,outcome,carc_code,rarc_code,explanation,eligible_amount,paid_amount,patient_amount)
 values(c.id,case claim_outcome when 'paid' then 'approved' when 'partially_paid' then 'adjusted' else 'denied' end,nullif(btrim(carc),''),nullif(btrim(rarc),''),note,c.submitted_amount,benefit,patient_share);
 update public.inpatient_claims set status=claim_outcome,benefit_amount=benefit,patient_responsibility=patient_share,payer_reference=nullif(btrim(payer_ref),''),adjudicated_at=now() where id=c.id;
 update public.inpatient_accounts set status='adjudicated' where id=c.account_id;
end $$;
revoke all on function public.record_inpatient_claim_adjudication(uuid,text,numeric,numeric,text,text,text,text) from public,anon;
grant execute on function public.record_inpatient_claim_adjudication(uuid,text,numeric,numeric,text,text,text,text) to authenticated;

-- 10. Audit the inpatient records ------------------------------------------------------------
do $$ declare t text; begin
 foreach t in array array['inpatient_admissions','inpatient_bed_assignments','inpatient_accounts','inpatient_charge_items','inpatient_claims','inpatient_claim_adjudications'] loop
  execute format('drop trigger if exists audit_row_change on public.%I',t);
  execute format('create trigger audit_row_change after insert or update or delete on public.%I for each row execute function private.audit_row_change()',t);
 end loop;
end $$;
